fn build_invalid_calendar_date_xlsx() -> Vec<u8> {
    build_minimal_xlsx(
        r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <dimension ref="A1:B2"/>
  <sheetData>
    <row r="1">
      <c r="A1" t="inlineStr"><is><t>id</t></is></c>
      <c r="B1" t="inlineStr"><is><t>reported_on</t></is></c>
    </row>
    <row r="2">
      <c r="A2"><v>1</v></c>
      <c r="B2" t="inlineStr"><is><t>2024-02-31</t></is></c>
    </row>
  </sheetData>
</worksheet>"#,
    )
}

fn strict_validation_schema(fields: &[(&str, FieldType)]) -> SchemaConfig {
    SchemaConfig {
        strict: true,
        fields: fields
            .iter()
            .map(|(name, field_type)| FieldConfig {
                name: (*name).to_string(),
                r#type: *field_type,
                nullable: false,
                sensitive: true,
                concept_uri: None,
                codelist: None,
                unit: None,
                language: None,
            })
            .collect(),
    }
}

async fn validate_temporary_project_workbook(
    bytes: &[u8],
    schema: &SchemaConfig,
    primary_key: Option<&str>,
) -> Result<(), registry_relay::error::IngestError> {
    let mut resource: ResourceConfig = serde_saphyr::from_str(
        r#"
id: workbook
source:
  type: file
  path: /runtime/workbook.xlsx
  format:
    xlsx:
      sheet: data
      header_row: 1
schema:
  strict: true
  fields: []
"#,
    )
    .expect("resource parses");
    resource.schema = schema.clone();
    resource.primary_key = primary_key.map(str::to_owned);
    let config = support::load_example_config_for_tests("format-xlsx-project-validation");
    validate_xlsx_source_bytes(&config, &resource, bytes).await
}

#[tokio::test]
async fn project_workbook_validation_accepts_exact_validated_bytes() {
    let bytes = build_strict_validation_xlsx(false, false);
    let schema =
        strict_validation_schema(&[("id", FieldType::Integer), ("name", FieldType::String)]);
    validate_temporary_project_workbook(&bytes, &schema, Some("id"))
        .await
        .expect("valid strict workbook");
}

#[tokio::test]
async fn project_workbook_validation_rejects_corrupt_formula_duplicate_and_extra_columns() {
    let id_name_schema =
        strict_validation_schema(&[("id", FieldType::Integer), ("name", FieldType::String)]);
    assert!(
        validate_temporary_project_workbook(b"not an xlsx zip", &id_name_schema, Some("id"))
            .await
            .is_err(),
        "corrupt workbook must fail"
    );
    let formula_schema =
        strict_validation_schema(&[("id", FieldType::Integer), ("amount", FieldType::Number)]);
    assert!(
        validate_temporary_project_workbook(&build_formula_xlsx(), &formula_schema, Some("id"))
            .await
            .is_err(),
        "formula workbook must fail"
    );
    assert!(
        validate_temporary_project_workbook(
            &build_strict_validation_xlsx(true, false),
            &id_name_schema,
            Some("id"),
        )
        .await
        .is_err(),
        "duplicate primary key must fail"
    );
    assert!(
        validate_temporary_project_workbook(
            &build_strict_validation_xlsx(false, true),
            &id_name_schema,
            Some("id"),
        )
        .await
        .is_err(),
        "strict extra column must fail"
    );
}

